E={}; errors=[]
def blob(p):
 p=Path(p); p=p if p.is_absolute() else R/p
 data=p.read_bytes();E[str(p.relative_to(R))]=hashlib.sha256(data).hexdigest();return data
def J(p):return json.loads(blob(p))
def need(c,msg):
 if not c:raise ValueError(msg)
IN=['rst','s_valid','s_data','s_last','m_ready','h_ready']
OUT=['s_ready','m_data','m_valid','m_last','h_valid','h_pad','h_truncate','h_length','h_original_length']
def number(v):return -1 if any(c in v.lower() for c in 'xz') else int(v)
def physical(p):
 rows={}
 for line in blob(p).decode().splitlines():
  w=line.split()
  if not w or w[0] not in ('PRE','POST'):continue
  vals=[number(x) for x in w[2:]];i=int(w[1]);row=rows.setdefault(i,{'cycle':i})
  if w[0]=='PRE':row['inputs']=dict(zip(IN,vals[:6]));vals=vals[6:]
  need(len(vals)==9,'wrong public output count')
  row[w[0].lower()]=dict(zip(OUT,vals))
 need(sorted(rows)==list(range(len(rows))),'physical cycle inventory')
 return [rows[i] for i in range(len(rows))]
def norm(rows):
 return [{'cycle':r['cycle'],'inputs':r['inputs'],**{ph:None if r['cycle']==0 and ph=='pre' else {k:v for k,v in r[ph].items() if k in ('s_ready','m_valid','h_valid') or r[ph]['h_valid' if k.startswith('h_') else 'm_valid']!=0} for ph in ('pre','post')}} for r in rows]
def MON(folder,rows,marker):
 result=J(folder/'result.json');z=blob(folder/'replay.log.gz');raw=gzip.decompress(z)
 need(hashlib.sha256(z).hexdigest()==result['compressed_log_sha256'],'gzip SHA')
 need(hashlib.sha256(raw).hexdigest()==result['raw_log_sha256']==result['execution']['log_sha256'],'raw MON SHA')
 need(hashlib.sha256(json.dumps(rows,sort_keys=True,separators=(',',':')).encode()).hexdigest()==result['rows_sha256'],'MON rows SHA')
 samples=[]
 for line in raw.decode().splitlines():
  if line.startswith('MON '):
   w=line.split();need(len(w)==5 and all(re.fullmatch('[01xz]{6}',s) for s in w[3:]),'MON malformed')
   samples.append((int(w[1]),w[2],w[3],w[4]))
 expected=[(i,ph) for i in range(len(rows)) for ph in ('pre','post') if i>0 or ph=='post']
 need([(x[0],x[1]) for x in samples]==expected,'MON sample inventory')
 need(result['complete'] and b'REPLAY_COMPLETE' in raw and result['samples']==len(expected) and result['cycles']==len(rows),'MON complete/count')
 need(result['trace_done_sample']==([len(rows)-1,'post'] if marker else None),'marker scope')
 slots=[]
 for slot,p in enumerate(result['properties']):
  failures=[];unknown=[];checks=0;endchecks=0
  for cycle,phase,a,k in samples:
   ac,ok=a[5-slot],k[5-slot];pos=[cycle,phase]
   if ac not in '01' or ac=='1' and ok not in '01':unknown.append(pos)
   elif ac=='1':
    checks+=1;endchecks+=int(marker and pos==[len(rows)-1,'post'])
    if ok=='0':failures.append(pos)
  need(p['id']==f'P{slot}' and p['checks']==checks and p['failures']==failures and p['unknown']==unknown,'MON parsed property disagreement')
  need(p['end_sample_checks']==endchecks,'MON marker checks')
  slots.append({'failures':failures,'unknown':unknown,'checks':checks})
 return result,slots
def VCD(p,slot):
 names={};scope=[];head=True;blocks=[];updates={};stepid=None
 for line in blob(p).decode().splitlines():
  w=line.split()
  if head:
   if line.startswith('$scope '):scope.append(w[2])
   elif line.startswith('$upscope'):scope.pop()
   elif line.startswith('$var '):
    if not scope and w[4]=='smt_step':stepid=w[3]
    if scope==['formal_top'] and w[4] in IN+OUT+['active','ok']:names[w[4]]=w[3]
   elif line.startswith('$enddefinitions'):head=False
  elif line.startswith('#'):
   if updates:blocks.append(updates)
   updates={}
  elif line.startswith('b'):
   value,ident=line[1:].split();updates[ident]=-1 if any(c in value.lower() for c in 'xz') else int(value,2)
  elif line and line[0] in '01xz':
   updates[line[1:]]=-1 if line[0] in 'xz' else int(line[0])
 if updates:blocks.append(updates)
 need(stepid is not None and all(k in names for k in IN+['active','ok']),'VCD pins missing')
 frames={};values={}
 for block in blocks:
  values.update(block)
  if set(names[k] for k in IN+['active','ok'])<=set(block):
   frames[values[stepid]]={k:values.get(v,-1) for k,v in names.items()}
 need(sorted(frames)==list(range(len(frames))),'VCD state range')
 bad=[i for i,f in frames.items() if i>0 and f['active']>=0 and f['ok']>=0 and (f['active']>>slot)&1 and not (f['ok']>>slot)&1]
 need(bad,'VCD selected failure missing');alarm=min(bad)
 return alarm,[{k:frames[i][k] for k in IN} for i in range(alarm+1)],frames
