expected={(a,rep,src,slot,mode) for a in ('B2_raw','C2_semantic') for rep in (1,2,3) for src in ['correct']+[f'N{i:02}' for i in range(1,13)] for slot in range(6) for mode in (('bmc','prove','cover') if src=='correct' else ('bmc',))}
actual={(j['arm'],j['repetition'],j['source'],j['slot'],j['mode']) for j in f['jobs']}
need(len(f['jobs'])==len(actual)==540 and actual==expected,'formal job inventory')
for j in f['jobs']:
 d=base/j['arm']/f"rep{j['repetition']}"/j['source']/f"P{j['slot']}-{j['mode']}"
 try:
